using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9: ZipArchiveEntry now sets the UTF-8 flag, causing non-ASCII
        // names to be encoded as UTF-8. The legacy Java consumer expects Shift-JIS.
        // Specifying entryNameEncoding suppresses the UTF-8 flag and encodes
        // entry names in the given encoding.
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create,
            Encoding.GetEncoding("shift_jis"));
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// .NET 9: [FromKeyedServices] no longer falls back to non-keyed services.
// Register as a keyed service to match the controller's attribute.
services.AddKeyedSingleton<ICache, RedisCache>("cache");

